CREATE COLUMN TABLE "TEST_AP"."APZ_COMMENTS" ("ID" VARCHAR(50) NOT NULL , "OBJTYPE" VARCHAR(20), "OBJECT_CODE" VARCHAR(50), "DETAIL_CODE" VARCHAR(50), "CREATE_DATE" DATE CS_DAYDATE, "CREATE_TIME" LONGDATE CS_LONGDATE, "CREATED_BY" VARCHAR(50), "CREATOR_NAME" VARCHAR(100), "COMMENTS" CLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE 